 24	var runSQLiteCommand = func(args ...string) ([]byte, error) {
 25		switch len(args) {
 26		case 3:
 27			if args[0] != "-json" {
 28				return nil, fmt.Errorf("unsupported sqlite query mode: %q", args[0])
 29			}
 30			return querySQLiteJSON(args[1], args[2])
 31		case 2:
 32			return querySQLiteRaw(args[0], args[1])
 33		default:
 34			return nil, fmt.Errorf("unsupported sqlite invocation with %d args", len(args))
 35		}
 36	}
