 47	func openSQLiteDB(path string) (*sql.DB, error) {
 48		db, err := sql.Open("sqlite", path)
 49		if err != nil {
 50			return nil, err
 51		}
 52		return db, nil
 53	}
 54	
 55	func querySQLiteJSON(path string, query string) ([]byte, error) {
 56		db, err := openSQLiteDB(path)
 57		if err != nil {
 58			return nil, err
 59		}
 60		defer func() {
 61			_ = db.Close()
 62		}()
 63	
 64		rows, err := db.Query(query)
 65		if err != nil {
 66			return nil, err
 67		}
 68		defer func() {
 69			_ = rows.Close()
 70		}()
 71	
 72		columns, err := rows.Columns()
 73		if err != nil {
 74			return nil, err
 75		}
 76	
 77		var result []map[string]string
 78		for rows.Next() {
 79			scanTargets := make([]sql.NullString, len(columns))
 80			dest := make([]any, len(columns))
 81			for i := range scanTargets {
 82				dest[i] = &scanTargets[i]
 83			}
 84			if err := rows.Scan(dest...); err != nil {
 85				return nil, err
 86			}
 87	
 88			row := make(map[string]string, len(columns))
 89			for i, col := range columns {
 90				if scanTargets[i].Valid {
 91					row[col] = scanTargets[i].String
 92				} else {
 93					row[col] = ""
 94				}
 95			}
 96			result = append(result, row)
 97		}
 98		if err := rows.Err(); err != nil {
 99			return nil, err
100		}
101	
102		if len(result) == 0 {
103			return []byte("[]"), nil
104		}
105		return json.Marshal(result)
106	}
