108	func querySQLiteRaw(path string, query string) ([]byte, error) {
109		db, err := openSQLiteDB(path)
110		if err != nil {
111			return nil, err
112		}
113		defer func() {
114			_ = db.Close()
115		}()
116	
117		var value sql.NullString
118		err = db.QueryRow(query).Scan(&value)
119		if errors.Is(err, sql.ErrNoRows) {
120			return []byte{}, nil
121		}
122		if err != nil {
123			return nil, err
124		}
125		if !value.Valid {
126			return []byte{}, nil
127		}
128		return []byte(value.String), nil
