158	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
159		if maxSize <= 0 {
160			return nil, errors.New("max-size must be greater than zero")
161		}
162		if len(content) == 0 {
163			return [][]byte{[]byte{}}, nil
164		}
165	
166		var chunks [][]byte
167		for start := 0; start < len(content); start += maxSize {
168			end := start + maxSize
169			if end > len(content) {
170				end = len(content)
171			}
172			chunk := make([]byte, end-start)
173			copy(chunk, content[start:end])
174			chunks = append(chunks, chunk)
175		}
