   166		var chunks [][]byte
   167		for start := 0; start < len(content); start += maxSize {
   168			end := start + maxSize
   169			if end > len(content) {
   170				end = len(content)
   171			}
   172			chunk := make([]byte, end-start)
   173			copy(chunk, content[start:end])
