343	// trimTranscriptHistory trims already-checkpointed entries from a cumulative
344	// kiro transcript using a stored offset keyed by `chatKey`. Returns the
345	// re-serialized trimmed JSON and true if trimming was applied, or (nil,
346	// false) if the full transcript should be used as-is. Each chat must pass a
347	// unique chatKey or it will share an offset bucket with other chats and
348	// silently drop history.
349	func (a *Agent) trimTranscriptHistory(raw []byte, chatKey string) ([]byte, bool) {
350		parsed, err := parseTranscript(raw)
351		if err != nil || len(parsed.History) == 0 {
