364			trimFrom = prev.Position
365		}
366	
367		// Only update offset when there are new entries to capture.
368		if trimFrom < totalLen {
369			_ = writeTranscriptOffset(offsetPath, transcriptOffset{
370				Key:      chatKey,
371				Position: totalLen,
372			})
