502	func (a *Agent) captureTranscriptForStop(cwd string, identity sessionIdentity) string {
503		// Try IDE workspace sessions first — the stop hook is fired by the
504		// IDE, so IDE data is the most accurate source. SKIP this when the
505		// resolver didn't identify an IDE chat: ensureIDETranscript would
506		// otherwise fall back to "latest IDE session" and silently checkpoint
507		// an unrelated chat for what's actually a CLI-only turn.
508		if identity.ideSessionID != "" {
509			if sessionRef, err := a.ensureIDETranscript(cwd, identity.entireSessionID, identity.ideSessionID); err == nil && sessionRef != "" {
510				return sessionRef
511			}
512		}
513		// CLI cached transcript fallback. Only attempt when the identity is
514		// either CLI-only (no ideSessionID) or has an explicit CLI
515		// conversation_id link from the payload. An IDE-bound stop without
516		// a proven conversation link must not fall through to
517		// ensureCachedTranscript, which would otherwise query SQLite by cwd
518		// and capture whatever unrelated CLI conversation happens to be
519		// latest in this repo under the IDE session's file.
520		if identity.ideSessionID == "" || identity.conversationID != "" {
521			if sessionRef, err := a.ensureCachedTranscript(cwd, identity.entireSessionID, identity.conversationID); err == nil && sessionRef != "" {
522				return sessionRef
523			}
524		}
525		return a.createPlaceholderTranscript(cwd, identity.entireSessionID)
526	}
