283	type transcriptOffset struct {
284		Key      string `json:"key"`
285		Position int    `json:"position"`
286	}
287	
288	// transcriptOffsetPath returns the offset file for a given chat/session key.
289	// Each Kiro chat (IDE session ID or CLI conversation ID) gets its own offset
290	// file so concurrent chats can never collapse into one shared bucket and
291	// silently trim each other's history.
292	func (a *Agent) transcriptOffsetPath(key string) string {
293		dir := filepath.Join(protocol.RepoRoot(), ".entire", "tmp")
294		if key == "" {
295			// No per-chat key (very early CLI flow before a conversation_id is
296			// known). Use the legacy single-bucket file so we don't churn its
297			// contents from elsewhere.
298			return filepath.Join(dir, "kiro-transcript-offset.json")
299		}
300		return filepath.Join(dir, "kiro-transcript-offset-"+sanitizeForFilename(key)+".json")
301	}
302	
303	// sanitizeForFilename strips characters that aren't safe in a filename across
304	// macOS/Linux/Windows. Kiro IDE session IDs are UUIDs (always safe); CLI
305	// conversation IDs are unverified, so we filter defensively.
306	func sanitizeForFilename(s string) string {
307		return strings.Map(func(r rune) rune {
308			switch {
309			case r >= 'a' && r <= 'z',
310				r >= 'A' && r <= 'Z',
311				r >= '0' && r <= '9',
312				r == '-', r == '_':
313				return r
314			default:
315				return '_'
316			}
317		}, s)
318	}
