320	func readTranscriptOffset(path string) transcriptOffset {
321		data, err := os.ReadFile(path)
322		if err != nil {
323			return transcriptOffset{}
324		}
325		var offset transcriptOffset
326		if err := json.Unmarshal(data, &offset); err != nil {
327			return transcriptOffset{}
328		}
329		return offset
330	}
331	
332	func writeTranscriptOffset(path string, offset transcriptOffset) error {
333		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
334			return err
335		}
336		data, err := json.Marshal(offset)
337		if err != nil {
338			return err
339		}
340		return os.WriteFile(path, data, 0o600)
341	}
