343	// trimTranscriptHistory trims already-checkpointed entries from a cumulative
344	// kiro transcript using a stored offset keyed by `chatKey`. Returns the
345	// re-serialized trimmed JSON and true if trimming was applied, or (nil,
346	// false) if the full transcript should be used as-is. Each chat must pass a
347	// unique chatKey or it will share an offset bucket with other chats and
348	// silently drop history.
349	func (a *Agent) trimTranscriptHistory(raw []byte, chatKey string) ([]byte, bool) {
350		parsed, err := parseTranscript(raw)
351		if err != nil || len(parsed.History) == 0 {
352			return nil, false
353		}
354	
355		offsetPath := a.transcriptOffsetPath(chatKey)
356		prev := readTranscriptOffset(offsetPath)
357		totalLen := len(parsed.History)
358	
359		trimFrom := 0
360		// Per-key offset files mean we don't need to compare keys here — file
361		// identity already binds the offset to one chat. The Key field is only
362		// stored for human-debuggability.
363		if prev.Position > 0 && prev.Position <= totalLen {
364			trimFrom = prev.Position
365		}
366	
367		// Only update offset when there are new entries to capture.
368		if trimFrom < totalLen {
369			_ = writeTranscriptOffset(offsetPath, transcriptOffset{
370				Key:      chatKey,
371				Position: totalLen,
372			})
373		}
374	
375		if trimFrom == 0 || trimFrom >= totalLen {
376			// No trimming needed (first capture) or no new entries since last
377			// capture. Return full transcript so the caller always has content —
378			// an empty transcript would cause the CLI finalize step to fail.
379			return nil, false
380		}
381	
382		parsed.History = parsed.History[trimFrom:]
383		filtered, err := json.Marshal(parsed)
384		if err != nil {
385			return nil, false
386		}
387		return filtered, true
388	}
