390	func (a *Agent) ensureIDETranscript(cwd string, entireSessionID string, ideSessionID string) (string, error) {
391		sessionsDir, err := ideWorkspaceSessionsDir(cwd)
392		if err != nil {
393			return "", err
394		}
395	
396		// Prefer the explicit IDE session ID resolved by the hook so multi-chat
397		// workspaces always read the transcript that actually fired the hook,
398		// not whichever chat happens to be newest. Fall back to "latest by
399		// dateCreated" only when the resolver couldn't identify a chat.
400		resolvedID := ""
401		if ideSessionID != "" && filepath.IsLocal(ideSessionID+".json") {
402			if _, statErr := os.Stat(filepath.Join(sessionsDir, ideSessionID+".json")); statErr == nil {
403				resolvedID = ideSessionID
404			}
405		}
406		if resolvedID == "" {
407			latest, err := latestIDESessionID(cwd)
408			if err != nil {
409				return "", err
410			}
411			resolvedID = latest
412		}
413		if !filepath.IsLocal(resolvedID + ".json") {
414			return "", fmt.Errorf("invalid session ID: %q", resolvedID)
415		}
416	
417		transcriptPath := filepath.Join(sessionsDir, resolvedID+".json")
418		transcriptData, err := os.ReadFile(transcriptPath)
419		if err != nil {
420			return "", fmt.Errorf("failed to read IDE transcript %s: %w", transcriptPath, err)
421		}
422	
423		// Enrich the IDE transcript with actual agent responses and tool calls.
424		// The IDE session format only stores "On it." as assistant content.
425		//
426		// Priority 1: Read Kiro IDE execution logs — these contain the full
427		// action trace (tool calls, responses, file modifications).
428		// Priority 2: Merge tool calls from post-tool-use hook JSONL file.
429		data := transcriptData
430		enriched := false
431		if chatSessionID := extractIDESessionID(transcriptData); chatSessionID != "" {
432			if execLogs, err := findExecutionLogsForSession(chatSessionID); err == nil && len(execLogs) > 0 {
433				if result := enrichIDETranscriptWithExecutionLogs(transcriptData, execLogs); result != nil {
434					data = result
435					enriched = true
436				}
437			}
438		}
439		if !enriched {
440			// Per-chat key matches what post-tool-use wrote so multi-chat
441			// workspaces don't cross-contaminate tool-call history.
442			if toolCalls := a.readAndClearToolCalls(resolvedID); len(toolCalls) > 0 {
443				if result := enrichIDETranscriptWithToolCalls(transcriptData, toolCalls); result != nil {
444					data = result
445				}
446			}
447		}
448	
449		// Trim already-checkpointed entries from cumulative IDE transcript.
450		// Key by the IDE session ID so different chats in the same workspace
451		// each track their own offset (IDE transcripts have no
452		// `conversation_id` field, so without an explicit key every chat would
453		// collapse into the same global bucket).
454		if filtered, ok := a.trimTranscriptHistory(data, resolvedID); ok {
455			data = filtered
456		}
457		data = injectTranscriptCLIVersion(data, currentCLIVersion())
458	
459		if parsed, parseErr := parseTranscript(data); parseErr == nil && len(parsed.History) == 0 {
460			return "", errors.New("IDE transcript has no history entries after trimming")
461		}
462	
463		cachePath, err := a.cacheTranscriptPath(cwd, entireSessionID)
464		if err != nil {
465			return "", err
466		}
467		if err := os.WriteFile(cachePath, data, 0o600); err != nil {
468			return "", fmt.Errorf("failed to write cached IDE transcript: %w", err)
469		}
470		return cachePath, nil
471	}
