 72	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
 73		data, err := os.ReadFile(sessionRef)
 74		if err != nil {
 75			return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
 76		}
 77	
 78		compacted, err := compactTranscriptBytes(data)
 79		if err != nil {
 80			return protocol.CompactTranscriptResponse{}, err
 81		}
 82	
 83		return protocol.CompactTranscriptResponse{
 84			Transcript: base64.StdEncoding.EncodeToString(compacted),
 85		}, nil
 86	}
