 88	func compactTranscriptBytes(data []byte) ([]byte, error) {
 89		transcript, err := parseTranscript(data)
 90		if err != nil {
 91			return nil, err
 92		}
 93		if len(transcript.History) == 0 {
 94			return nil, errors.New("transcript has no history entries")
 95		}
 96		cliVersion := compactCLIVersion(transcript)
 97	
 98		var buf bytes.Buffer
 99		for i := range transcript.History {
100			entry := transcript.History[i]
101	
102			if prompt := extractUserPrompt(entry.User.Content); prompt != "" {
103				if err := writeCompactTranscriptLine(&buf, compactTranscriptLine{
104					V:          1,
105					Agent:      compactTranscriptAgent,
106					CLIVersion: cliVersion,
107					Type:       "user",
108					TS:         entry.User.Timestamp,
