  1	package kiro
  2	
  3	import (
  4		"encoding/json"
  5		"os"
  6		"path/filepath"
  7		"strings"
  8		"testing"
  9	)
 10	
 11	func withRuntimeGOOS(t *testing.T, goos string) {
 12		t.Helper()
 13		previous := runtimeGOOS
 14		runtimeGOOS = goos
 15		t.Cleanup(func() {
 16			runtimeGOOS = previous
 17		})
 18	}
 19	
 20	func TestInstallHooksWritesCLIAndIDEHooksAndTrustedCommands(t *testing.T) {
 21		repoRoot := t.TempDir()
 22		t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
 23	
 24		count, err := New().InstallHooks(false, false)
 25		if err != nil {
 26			t.Fatalf("InstallHooks() error = %v", err)
 27		}
 28		if count != 9 {
 29			t.Fatalf("InstallHooks() count = %d, want %d", count, 9)
 30		}
 31	
 32		cliPath := filepath.Join(repoRoot, ".kiro", "agents", "entire.json")
 33		if _, err := os.Stat(cliPath); err != nil {
 34			t.Fatalf("expected CLI hook file at %s: %v", cliPath, err)
 35		}
 36	
 37		idePath := filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")
 38		if _, err := os.Stat(idePath); err != nil {
 39			t.Fatalf("expected IDE hook file at %s: %v", idePath, err)
 40		}
 41	
 42		settingsPath := filepath.Join(repoRoot, ".vscode", "settings.json")
 43		data, err := os.ReadFile(settingsPath)
 44		if err != nil {
 45			t.Fatalf("read settings.json: %v", err)
 46		}
 47		var settings map[string][]string
 48		if err := json.Unmarshal(data, &settings); err != nil {
 49			t.Fatalf("unmarshal settings.json: %v", err)
 50		}
 51		commands := settings["kiroAgent.trustedCommands"]
 52		if len(commands) != 1 || commands[0] != "sh -c 'entire hooks *" {
 53			t.Fatalf("trusted commands = %#v, want [\"sh -c 'entire hooks *\"]", commands)
 54		}
 55	}
 56	
 57	func TestInstallHooksIsIdempotentUnlessForced(t *testing.T) {
 58		repoRoot := t.TempDir()
 59		t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
 60	
 61		if _, err := New().InstallHooks(false, false); err != nil {
 62			t.Fatalf("first InstallHooks() error = %v", err)
 63		}
 64	
 65		count, err := New().InstallHooks(false, false)
 66		if err != nil {
 67			t.Fatalf("second InstallHooks() error = %v", err)
 68		}
 69		if count != 0 {
 70			t.Fatalf("second InstallHooks() count = %d, want %d", count, 0)
 71		}
 72	
 73		count, err = New().InstallHooks(false, true)
 74		if err != nil {
 75			t.Fatalf("forced InstallHooks() error = %v", err)
 76		}
 77		if count != 9 {
 78			t.Fatalf("forced InstallHooks() count = %d, want %d", count, 9)
 79		}
 80	}
 81	
 82	func TestInstallHooksLocalDevUsesLocalCommands(t *testing.T) {
 83		repoRoot := t.TempDir()
 84		t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
 85	
 86		if _, err := New().InstallHooks(true, false); err != nil {
 87			t.Fatalf("InstallHooks() error = %v", err)
 88		}
 89	
 90		cliPath := filepath.Join(repoRoot, ".kiro", "agents", "entire.json")
 91		cliData, err := os.ReadFile(cliPath)
 92		if err != nil {
 93			t.Fatalf("read cli hooks: %v", err)
 94		}
 95		if !strings.Contains(string(cliData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro stop`) {
 96			t.Fatalf("cli hooks = %s", cliData)
 97		}
 98	
 99		idePath := filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")
100		ideData, err := os.ReadFile(idePath)
101		if err != nil {
102			t.Fatalf("read ide hook: %v", err)
103		}
104		if !strings.Contains(string(ideData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro stop`) {
105			t.Fatalf("ide hook = %s", ideData)
106		}
107	
108		settingsPath := filepath.Join(repoRoot, ".vscode", "settings.json")
109		settingsData, err := os.ReadFile(settingsPath)
