111			t.Fatalf("read settings: %v", err)
112		}
113		if !strings.Contains(string(settingsData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks *`) {
114			t.Fatalf("settings = %s", settingsData)
