190		t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
191	
192		settingsDir := filepath.Join(repoRoot, ".vscode")
193		if err := os.MkdirAll(settingsDir, 0o750); err != nil {
194			t.Fatalf("mkdir settings dir: %v", err)
