 46	// RewindList runs `entire checkpoint rewind --list` and parses the JSON output.
 47	func RewindList(t *testing.T, dir string) []RewindPoint {
 48		t.Helper()
 49		out := run(t, dir, "checkpoint", "rewind", "--list")
 50	
 51		// Newer entire versions print a deprecation notice for `rewind` ahead of
 52		// the JSON; parse from the start of the array.
 53		jsonOut := out
 54		if idx := strings.Index(out, "["); idx > 0 {
 55			jsonOut = out[idx:]
 56		}
 57	
 58		var points []RewindPoint
 59		if err := json.Unmarshal([]byte(jsonOut), &points); err != nil {
 60			t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
 61		}
 62		return points
 63	}
 64	
 65	// Rewind runs `entire checkpoint rewind --to <id>`. Returns an error instead of
 66	// failing the test, since callers may test failure cases.
 67	func Rewind(t *testing.T, dir, id string) error {
 68		t.Helper()
 69		return runErr(dir, "checkpoint", "rewind", "--to", id)
 70	}
 71	
 72	// RewindLogsOnly runs `entire checkpoint rewind --to <id> --logs-only`.
 73	func RewindLogsOnly(t *testing.T, dir, id string) error {
 74		t.Helper()
 75		return runErr(dir, "checkpoint", "rewind", "--to", id, "--logs-only")
 76	}
 77	
 78	// run executes an `entire` subcommand in dir and fails the test on error.
 79	func run(t *testing.T, dir string, args ...string) string {
 80		t.Helper()
 81		cmd := exec.Command(BinPath(), args...)
 82		cmd.Dir = dir
 83		cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 84	
 85		out, err := cmd.CombinedOutput()
 86		if err != nil {
 87			t.Fatalf("entire %s failed: %v\n%s", strings.Join(args, " "), err, out)
 88		}
 89		return strings.TrimSpace(string(out))
 90	}
 91	
 92	// runErr executes an `entire` subcommand in dir and returns any error.
 93	func runErr(dir string, args ...string) error {
 94		cmd := exec.Command(BinPath(), args...)
 95		cmd.Dir = dir
 96		cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 97	
 98		out, err := cmd.CombinedOutput()
 99		if err != nil {
100			return &ExecError{
101				Args:   args,
102				Err:    err,
103				Output: string(out),
104			}
105		}
106		return nil
107	}
108	
109	// ExecError wraps an entire CLI execution failure with its output.
110	type ExecError struct {
111		Args   []string
112		Err    error
113		Output string
114	}
115	
116	func (e *ExecError) Error() string {
117		return "entire " + strings.Join(e.Args, " ") + ": " + e.Err.Error() + "\n" + e.Output
118	}
119	
120	func (e *ExecError) Unwrap() error {
121		return e.Err
122	}

